@Component
public class SpringBootProjectGenerator {
    private final ObjectMapper json; private final String bootVersion; private final RelationshipCodeMapper relationshipCode;
    public SpringBootProjectGenerator(ObjectMapper json,@Value("${codegen.spring-boot-version}") String bootVersion,RelationshipCodeMapper relationshipCode){this.json=json;this.bootVersion=bootVersion;this.relationshipCode=relationshipCode;}
    public Map<String,byte[]> generate(GenerationModel model){try{Map<String,byte[]>files=new LinkedHashMap<>();String root=model.artifactId()+"/",backend=root+"backend/",java=backend+"src/main/java/"+model.packageName().replace('.','/')+"/";put(files,root+"README.md",projectReadme(model));put(files,backend+"pom.xml",pom(model));put(files,backend+"README.md",readme(model));String definition=json.writerWithDefaultPrettyPrinter().writeValueAsString(model);put(files,backend+"app-definition.json",definition);put(files,backend+"src/main/resources/app-definition.json",definition);put(files,backend+"src/main/resources/application.properties",h2());put(files,backend+"src/main/resources/application-postgres.properties",postgres());put(files,java+"Application.java",application(model));put(files,java+"exception/ResourceNotFoundException.java",notFound(model));put(files,java+"exception/GlobalExceptionHandler.java",handler(model));put(files,java+"controller/MetaController.java",meta(model));for(var entity:model.entities()){put(files,java+"entity/"+entity.javaName()+".java",entity(model,entity));put(files,java+"repository/"+entity.javaName()+"Repository.java",repository(model,entity));put(files,java+"dto/"+entity.javaName()+"Request.java",request(model,entity));put(files,java+"dto/"+entity.javaName()+"Response.java",response(model,entity));put(files,java+"service/"+entity.javaName()+"Service.java",service(model,entity));put(files,java+"controller/"+entity.javaName()+"Controller.java",controller(model,entity));}new MobileProjectFiles().add(files,model,backend,java);put(files,backend+"src/test/java/"+model.packageName().replace('.','/')+"/ApplicationTests.java",test(model));addMobileTemplate(files,root+"mobile/");return files;}catch(Exception e){throw new IllegalStateException("No se pudo renderizar el proyecto",e);}}

    private void addMobileTemplate(Map<String,byte[]> files,String target) throws Exception {try(InputStream resource=getClass().getResourceAsStream("/codegen/mobile-template.zip")){if(resource==null)throw new IllegalStateException("No se encontró mobile-template.zip en el classpath");try(ZipInputStream zip=new ZipInputStream(resource)){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry()){String name=entry.getName().replace('\\','/');if(name.startsWith("/")||name.contains("../")||name.contains(":"))throw new IllegalStateException("Ruta insegura en mobile-template: "+name);if(entry.isDirectory()||isBuildArtifact(name))continue;files.put(target+name,zip.readAllBytes());}}}}

    static boolean isBuildArtifact(String path){
        String normalized=path.replace('\\','/').toLowerCase(Locale.ROOT);
        for(String segment:normalized.split("/")){
            if(List.of("build",".dart_tool",".idea",".gradle","coverage").contains(segment))return true;
        }
        return normalized.endsWith(".apk")||normalized.endsWith(".aab")||normalized.endsWith(".gguf")
            ||normalized.endsWith("/.flutter-plugins-dependencies")||normalized.equals(".flutter-plugins-dependencies")
            ||normalized.equals("android/local.properties");
    }

    private String projectReadme(GenerationModel m){return "# "+m.applicationName()+"\n\nProyecto generado por Collab CASE. Después de la generación, `backend` y `mobile` funcionan directamente entre sí; Collab CASE no participa en ejecución.\n\n## Backend\n\n```bash\ncd backend\nmvn spring-boot:run\n```\n\n## Android por USB\n\n```bash\nadb devices\nadb reverse tcp:8081 tcp:8081\ncd mobile\nflutter pub get\nflutter run --dart-define=BACKEND_URL=http://127.0.0.1:8081\n```\n\n## IA local\n\nEn la pantalla principal selecciona un archivo GGUF almacenado en el teléfono. El modelo se ejecuta localmente y no necesita el backend ni Internet.\n\n## Producción\n\n```bash\ncd mobile\nflutter build apk --release --dart-define=BACKEND_URL=https://URL_BACKEND_DESPLEGADO\n```\n\nPuedes añadir `--dart-define=MOBILE_API_TOKEN=...` si el backend fue configurado con token móvil. Un token incorporado en una APK no es un secreto fuerte.\n";}
    @SuppressWarnings("unchecked") public Map<String,Object> appDefinition(GenerationModel model){return json.convertValue(model,Map.class);}
    private String pom(GenerationModel m){return """
            <?xml version="1.0" encoding="UTF-8"?>
            <project xmlns="http://maven.apache.org/POM/4.0.0" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd">
              <modelVersion>4.0.0</modelVersion><parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId><version>%s</version><relativePath/></parent>
              <groupId>com.collabcase.generated</groupId><artifactId>%s</artifactId><version>0.0.1-SNAPSHOT</version><name>%s</name>
              <properties><java.version>21</java.version></properties><dependencies>
                <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-webmvc</artifactId></dependency>
                <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-data-jpa</artifactId></dependency>
                <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-validation</artifactId></dependency>
                <dependency><groupId>com.h2database</groupId><artifactId>h2</artifactId><scope>runtime</scope></dependency>
                <dependency><groupId>org.postgresql</groupId><artifactId>postgresql</artifactId><scope>runtime</scope></dependency>
                <dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-webmvc-test</artifactId><scope>test</scope></dependency>
              </dependencies><build><plugins><plugin><groupId>org.springframework.boot</groupId><artifactId>spring-boot-maven-plugin</artifactId></plugin></plugins></build>
            </project>
            """.formatted(bootVersion,m.artifactId(),xml(m.applicationName()));}
    private String application(GenerationModel m){return "package "+m.packageName()+";\nimport org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;\n@SpringBootApplication public class Application { public static void main(String[] args){SpringApplication.run(Application.class,args);} }\n";}
    private String entity(GenerationModel m,GenerationEntity e){StringBuilder b=new StringBuilder("package "+m.packageName()+".entity;\nimport jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.BigDecimal;\n@Entity\n@Table(name=\""+e.tableName()+"\")\n");if(isRoot(m,e))b.append("@Inheritance(strategy=InheritanceType.JOINED)\n");b.append("public class ").append(e.javaName());if(e.parentJavaName()!=null)b.append(" extends ").append(e.parentJavaName());b.append(" {\n");if(e.parentJavaName()==null){b.append("  @Id\n");if(e.id().generated())b.append("  @GeneratedValue(strategy=GenerationType.").append(e.id().idGenerationStrategy()).append(")\n");b.append("  private ").append(e.id().javaType()).append(" ").append(e.id().javaName()).append(";\n  @Column(nullable=false,unique=true,updatable=false) private UUID syncId;\n  @Version private Long version;\n  @PrePersist void ensureSyncId(){if(syncId==null)syncId=UUID.randomUUID();}\n");}for(var a:e.attributes())if(!a.javaName().equals(e.id().javaName()))b.append("  private ").append(a.javaType()).append(" ").append(a.javaName()).append(";\n");b.append(relationshipFields(m,e));b.append("  public ").append(e.javaName()).append("() {}\n");if(e.parentJavaName()==null){b.append(accessors(e.id().javaType(),e.id().javaName()));b.append(accessors("UUID","syncId"));b.append(accessors("Long","version"));}for(var a:e.attributes())if(!a.javaName().equals(e.id().javaName()))b.append(accessors(a.javaType(),a.javaName()));for(var method:e.methods()){b.append("  ").append(method.visibility()).append(" ").append(method.returnType()).append(" ").append(method.javaName()).append("(");for(int i=0;i<method.parameters().size();i++){if(i>0)b.append(", ");var p=method.parameters().get(i);b.append(p.javaType()).append(" ").append(p.javaName());}b.append("){ throw new UnsupportedOperationException(\"TODO: implement generated UML method\"); }\n");}return b.append("}\n").toString();}
    private String relationshipFields(GenerationModel m,GenerationEntity e){StringBuilder b=new StringBuilder();for(GenerationRelationship r:m.relationships()){boolean source=e.sourceElementId().equals(r.sourceId()),target=e.sourceElementId().equals(r.targetId());if("ClassDependency".equals(r.originalType())||"ClassInheritance".equals(r.originalType())||"ClassRealization".equals(r.originalType()))continue;if(r.multiple()){GenerationEntity sourceEntity=entityById(m,r.sourceId()),targetEntity=entityById(m,r.targetId());boolean bidirectional="ClassBidirectional".equals(r.originalType());GenerationEntity owner=bidirectional&&sourceEntity.tableName().compareTo(targetEntity.tableName())>0?targetEntity:sourceEntity;GenerationEntity inverse=owner==sourceEntity?targetEntity:sourceEntity;String ownerField=lower(inverse.javaName())+"Set";if(e==owner)b.append(manyToManyOwner(owner,inverse,ownerField));else if(bidirectional&&e==inverse)b.append(manyToManyInverse(owner.javaName(),lower(owner.javaName())+"Set",ownerField));continue;}if("ClassBidirectional".equals(r.originalType())){var sourceMapping=relationshipCode.fromSource(r.sourceCardinality(),r.targetCardinality());String ownerField=lower(r.targetJavaName())+(sourceMapping.collection()?"List":"");if(source)b.append(relationField(r.targetJavaName(),lower(r.targetJavaName()),sourceMapping,false,false,null));else if(target)b.append(relationField(r.sourceJavaName(),lower(r.sourceJavaName()),relationshipCode.fromTarget(r.sourceCardinality(),r.targetCardinality()),false,false,ownerField));}else if("ClassUnidirectional".equals(r.originalType())&&source)b.append(relationField(r.targetJavaName(),lower(r.targetJavaName()),relationshipCode.fromSource(r.sourceCardinality(),r.targetCardinality()),false,false,null));else if(("ClassAggregation".equals(r.originalType())||"ClassComposition".equals(r.originalType()))&&target)b.append(relationField(r.sourceJavaName(),lower(r.sourceJavaName()),relationshipCode.fromTarget(r.sourceCardinality(),r.targetCardinality()),"ClassComposition".equals(r.originalType()),"ClassComposition".equals(r.originalType()),null));}return b.toString();}
    private String manyToManyOwner(GenerationEntity owner,GenerationEntity target,String field){String table=owner.tableName().compareTo(target.tableName())<=0?owner.tableName()+"_"+target.tableName():target.tableName()+"_"+owner.tableName();String join=owner.tableName()+"_"+owner.id().javaName(),inverse=target.tableName()+"_"+target.id().javaName();return "  @ManyToMany\n  @JoinTable(name=\""+table+"\",joinColumns=@JoinColumn(name=\""+join+"\"),inverseJoinColumns=@JoinColumn(name=\""+inverse+"\"))\n  private Set<"+target.javaName()+"> "+field+" = new LinkedHashSet<>();\n"+accessors("Set<"+target.javaName()+">",field);}
    private String manyToManyInverse(String ownerType,String field,String mappedBy){return "  @ManyToMany(mappedBy=\""+mappedBy+"\")\n  private Set<"+ownerType+"> "+field+" = new LinkedHashSet<>();\n"+accessors("Set<"+ownerType+">",field);}
    private String relationField(String type,String name,RelationshipCodeMapper.JpaMapping mapping,boolean cascade,boolean orphan,String mappedBy){String annotation="@"+mapping.annotation();List<String>args=new ArrayList<>();if(cascade)args.add("cascade=CascadeType.ALL");if(orphan&&mapping.collection())args.add("orphanRemoval=true");if(mappedBy!=null)args.add("mappedBy=\""+mappedBy+"\"");if(!args.isEmpty())annotation+="("+String.join(",",args)+")";String field=mapping.collection()?name+"List":name;String javaType=mapping.collection()?"List<"+type+">":type;return "  "+annotation+"\n  private "+javaType+" "+field+(mapping.collection()?" = new ArrayList<>()":"")+";\n"+accessors(javaType,field);}
    private String repository(GenerationModel m,GenerationEntity e){return "package "+m.packageName()+".repository;\nimport java.util.*;\nimport org.springframework.data.jpa.repository.JpaRepository;import "+m.packageName()+".entity."+e.javaName()+";\npublic interface "+e.javaName()+"Repository extends JpaRepository<"+e.javaName()+", "+idType(m,e)+"> { Optional<"+e.javaName()+"> findBySyncId(UUID syncId); }\n";}
    private String request(GenerationModel m,GenerationEntity e){StringBuilder b=new StringBuilder("package "+m.packageName()+".dto;\nimport java.util.*;import java.time.*;import java.math.BigDecimal;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;\n@JsonIgnoreProperties(ignoreUnknown=true) public record "+e.javaName()+"Request(");List<String>fields=new ArrayList<>();if(!e.id().generated()&&e.parentJavaName()==null)fields.add(e.id().javaType()+" "+e.id().javaName());for(var a:e.attributes())if(!a.javaName().equals(e.id().javaName()))fields.add(a.javaType()+" "+a.javaName());for(var r:m.relationships())if(ownsManyToMany(m,e,r)){GenerationEntity other=entityById(m,e.sourceElementId().equals(r.sourceId())?r.targetId():r.sourceId());fields.add("Set<"+idType(m,other)+"> "+lower(other.javaName())+"Ids");}return b.append(String.join(",",fields)).append(") {}\n").toString();}
    private String response(GenerationModel m,GenerationEntity e){StringBuilder b=new StringBuilder("package "+m.packageName()+".dto;\nimport java.util.*;import java.time.*;import java.math.BigDecimal;\npublic record "+e.javaName()+"Response(");List<String>fields=new ArrayList<>();fields.add(idType(m,e)+" id");fields.add("UUID syncId");fields.add("Long version");for(var a:e.attributes())if(!a.javaName().equals(e.id().javaName()))fields.add(a.javaType()+" "+a.javaName());for(var r:m.relationships())if(ownsManyToMany(m,e,r)){GenerationEntity other=entityById(m,e.sourceElementId().equals(r.sourceId())?r.targetId():r.sourceId());fields.add("Set<"+idType(m,other)+"> "+lower(other.javaName())+"Ids");}return b.append(String.join(",",fields)).append(") {}\n").toString();}
    private String service(GenerationModel m,GenerationEntity e){String n=e.javaName(),id=idType(m,e);StringBuilder setters=new StringBuilder(),args=new StringBuilder("entity.get"+cap(idField(m,e))+"(),entity.getSyncId(),entity.getVersion()"),relationFields=new StringBuilder(),relationParams=new StringBuilder(),relationAssignments=new StringBuilder();if(!e.id().generated()&&e.parentJavaName()==null)setters.append("entity.set").append(cap(e.id().javaName())).append("(request.").append(e.id().javaName()).append("());");for(var a:e.attributes())if(!a.javaName().equals(e.id().javaName())){setters.append("entity.set").append(cap(a.javaName())).append("(request.").append(a.javaName()).append("());");args.append(",entity.get").append(cap(a.javaName())).append("()");}for(var r:m.relationships())if(ownsManyToMany(m,e,r)){GenerationEntity other=entityById(m,e.sourceElementId().equals(r.sourceId())?r.targetId():r.sourceId());String base=lower(other.javaName()),repo=base+"Repository",field=base+"Set",ids=base+"Ids";relationFields.append("private final ").append(other.javaName()).append("Repository ").append(repo).append(";");relationParams.append(",").append(other.javaName()).append("Repository ").append(repo);relationAssignments.append("this.").append(repo).append("=").append(repo).append(";");setters.append("entity.set").append(cap(field)).append("(request.").append(ids).append("()==null?new LinkedHashSet<>():request.").append(ids).append("().stream().map(value->").append(repo).append(".findById(value).orElseThrow(()->new ResourceNotFoundException(\"").append(other.javaName()).append(" not found\"))).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new)));");args.append(",entity.get").append(cap(field)).append("().stream().map(").append(other.javaName()).append("::get").append(cap(idField(m,other))).append(").collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new))");}return "package "+m.packageName()+".service;\nimport java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import "+m.packageName()+".entity.*;import "+m.packageName()+".repository.*;import "+m.packageName()+".dto.*;import "+m.packageName()+".exception.ResourceNotFoundException;import "+m.packageName()+".mobile.MobileChangeLogService;\n@Service public class "+n+"Service { private final "+n+"Repository repository;private final MobileChangeLogService changes;"+relationFields+" public "+n+"Service("+n+"Repository repository,MobileChangeLogService changes"+relationParams+"){this.repository=repository;this.changes=changes;"+relationAssignments+"} @Transactional(readOnly=true) public List<"+n+"Response> findAll(){return repository.findAll().stream().map(this::response).toList();} @Transactional(readOnly=true) public "+n+"Response findById("+id+" id){return response(find(id));} @Transactional public "+n+"Response create("+n+"Request request){"+n+" entity=new "+n+"();apply(entity,request);entity=repository.saveAndFlush(entity);var result=response(entity);changes.upsert(\""+n+"\",entity.getSyncId(),entity.getVersion(),result);return result;} @Transactional public "+n+"Response update("+id+" id,"+n+"Request request){"+n+" entity=find(id);apply(entity,request);entity=repository.saveAndFlush(entity);var result=response(entity);changes.upsert(\""+n+"\",entity.getSyncId(),entity.getVersion(),result);return result;} @Transactional public void delete("+id+" id){var entity=find(id);changes.delete(\""+n+"\",entity.getSyncId(),entity.getVersion());repository.delete(entity);} private "+n+" find("+id+" id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException(\""+n+" not found\"));} public void applyMobile("+n+" entity,"+n+"Request request){apply(entity,request);} public "+n+"Response response("+n+" entity){return new "+n+"Response("+args+");} private void apply("+n+" entity,"+n+"Request request){"+setters+"}}\n";}
    private String controller(GenerationModel m,GenerationEntity e){String n=e.javaName(),id=idType(m,e);return "package "+m.packageName()+".controller;\nimport java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import "+m.packageName()+".dto.*;import "+m.packageName()+".service."+n+"Service;\n@RestController @RequestMapping(\""+e.apiPath()+"\") public class "+n+"Controller {private final "+n+"Service service;public "+n+"Controller("+n+"Service service){this.service=service;}@GetMapping public List<"+n+"Response> all(){return service.findAll();}@GetMapping(\"/{id}\") public "+n+"Response one(@PathVariable "+id+" id){return service.findById(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public "+n+"Response create(@Valid @RequestBody "+n+"Request request){return service.create(request);}@PutMapping(\"/{id}\") public "+n+"Response update(@PathVariable "+id+" id,@Valid @RequestBody "+n+"Request request){return service.update(id,request);}@DeleteMapping(\"/{id}\") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable "+id+" id){service.delete(id);}}\n";}
    private String notFound(GenerationModel m){return "package "+m.packageName()+".exception;public class ResourceNotFoundException extends RuntimeException{public ResourceNotFoundException(String message){super(message);}}\n";}
    private String handler(GenerationModel m){return "package "+m.packageName()+".exception;import java.util.Map;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<Map<String,String>> notFound(ResourceNotFoundException e){return ResponseEntity.status(404).body(Map.of(\"message\",e.getMessage()));}@ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<Map<String,String>> conflict(){return ResponseEntity.status(409).body(Map.of(\"message\",\"No se pudo persistir el recurso por una restricción de datos.\"));}}\n";}
    private String meta(GenerationModel m){return "package "+m.packageName()+".controller;import java.io.*;import java.util.*;import org.springframework.web.bind.annotation.*;import tools.jackson.databind.ObjectMapper;@RestController @RequestMapping(\"/api\") public class MetaController{private final ObjectMapper json;public MetaController(ObjectMapper json){this.json=json;}@GetMapping(\"/health\") public Map<String,String> health(){return Map.of(\"status\",\"UP\");}@GetMapping(\"/meta\") public Map<String,Object> meta(){return Map.of(\"applicationName\",\""+java(m.applicationName())+"\",\"schemaVersion\",1,\"entities\",List.of("+m.entities().stream().map(e->"\""+java(e.javaName())+"\"").reduce((a,b)->a+","+b).orElse("")+"));}@GetMapping(\"/definition\") public Object definition() throws IOException{try(InputStream in=getClass().getResourceAsStream(\"/app-definition.json\")){return json.readValue(in,Object.class);}}}\n";}
    private String test(GenerationModel m){StringBuilder posts=new StringBuilder(),joins=new StringBuilder();for(var e:m.entities())posts.append("assertCreated(\"").append(e.apiPath()).append("\",\"").append(java(sampleRequest(m,e))).append("\");");for(var r:m.relationships())if(r.multiple()){GenerationEntity source=entityById(m,r.sourceId()),target=entityById(m,r.targetId());if(!source.id().generated()&&!target.id().generated()){String table=source.tableName().compareTo(target.tableName())<=0?source.tableName()+"_"+target.tableName():target.tableName()+"_"+source.tableName();joins.append("assertEquals(1,jdbc.queryForObject(\"select count(*) from ").append(table).append("\",Integer.class));");}}return "package "+m.packageName()+";import java.net.*;import java.net.http.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.boot.test.context.SpringBootTest;import static org.junit.jupiter.api.Assertions.*;@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class ApplicationTests{@Value(\"${local.server.port}\") int port;@Autowired JdbcTemplate jdbc;private HttpResponse<String> get(String path)throws Exception{return HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(\"http://localhost:\"+port+path)).GET().build(),HttpResponse.BodyHandlers.ofString());}private void assertCreated(String path,String body)throws Exception{var post=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(\"http://localhost:\"+port+path)).header(\"Content-Type\",\"application/json\").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());assertEquals(201,post.statusCode(),post.body());assertTrue(post.body().matches(\"(?s).*\\\"id\\\"\\s*:\\s*(?!null).*\"),post.body());assertTrue(post.body().contains(\"\\\"syncId\\\"\"),post.body());assertTrue(post.body().contains(\"\\\"version\\\"\"),post.body());assertEquals(200,get(path).statusCode());}@Test void generatedApiWorks()throws Exception{var health=get(\"/api/health\");assertEquals(200,health.statusCode());assertTrue(health.body().contains(\"UP\"));assertEquals(200,get(\"/api/meta\").statusCode());assertEquals(200,get(\"/api/mobile/definition\").statusCode());"+posts+joins+"var changes=get(\"/api/mobile/changes?after=0\");assertEquals(200,changes.statusCode());assertTrue(changes.body().contains(\"UPSERT\"),changes.body());}}\n";}
    private String h2(){return "server.port=8081\nspring.datasource.url=jdbc:h2:file:./data/generated-app\nspring.datasource.username=sa\nspring.datasource.password=\nspring.jpa.hibernate.ddl-auto=update\nspring.jpa.open-in-view=false\nmobile.api-token=${MOBILE_API_TOKEN:}\n";}
    private String postgres(){return "spring.datasource.url=${DB_URL}\nspring.datasource.username=${DB_USERNAME}\nspring.datasource.password=${DB_PASSWORD}\nspring.jpa.hibernate.ddl-auto=update\nspring.jpa.open-in-view=false\nmobile.api-token=${MOBILE_API_TOKEN:}\n";}
    private String readme(GenerationModel m){StringBuilder endpoints=new StringBuilder();for(var e:m.entities())endpoints.append("- ").append(e.apiPath()).append("\n");return "# "+m.applicationName()+"\n\nBackend Spring Boot generado determinísticamente desde Collab CASE.\n\n## Requisitos\n\n- Java 21\n- Maven\n\n## Ejecución local con H2\n\n```bash\nmvn spring-boot:run\n```\n\nEl servidor local usa el puerto `8081`.\n\n## PostgreSQL opcional\n\nDefine `DB_URL`, `DB_USERNAME` y `DB_PASSWORD`, y ejecuta:\n\n```bash\nmvn spring-boot:run -Dspring-boot.run.profiles=postgres\n```\n\n## Mobile / offline sync\n\n- `GET /api/mobile/definition`: definición de esta aplicación.\n- `GET /api/mobile/changes?after=0`: cambios incrementales ordenados por cursor.\n- `POST /api/mobile/sync`: aplica mutations idempotentes y devuelve cambios/conflictos.\n\nCada registro conserva su PK de dominio y añade `syncId` UUID y `version` optimista. `mutationId` evita reprocesar una mutation y `changeId` es el cursor incremental. `MOBILE_API_TOKEN` es opcional: vacío permite desarrollo local; si se configura, el cliente debe enviar `X-Mobile-Token`.\n\n## Endpoints CRUD\n\n- /api/health\n- /api/meta\n- /api/definition\n"+endpoints;}
    private String sampleRequest(GenerationModel m,GenerationEntity e){List<String>values=new ArrayList<>();if(!e.id().generated()&&e.parentJavaName()==null)values.add("\""+e.id().javaName()+"\":"+sampleValue(e.id().javaType()));for(var a:e.attributes())if(!a.javaName().equals(e.id().javaName()))values.add("\""+a.javaName()+"\":"+sampleValue(a.javaType()));for(var r:m.relationships())if(ownsManyToMany(m,e,r)){GenerationEntity other=entityById(m,e.sourceElementId().equals(r.sourceId())?r.targetId():r.sourceId());if(!other.id().generated())values.add("\""+lower(other.javaName())+"Ids\":["+sampleValue(other.id().javaType())+"]");}return "{"+String.join(",",values)+"}";}
    private String sampleValue(String type){return switch(type){case "Integer","Long","Double","Float","BigDecimal"->"1";case "Boolean"->"true";case "UUID"->"\"00000000-0000-0000-0000-000000000001\"";case "LocalDate"->"\"2026-01-01\"";case "LocalDateTime"->"\"2026-01-01T12:00:00\"";default->"\"test\"";};}
    private boolean isRoot(GenerationModel m,GenerationEntity e){return e.parentJavaName()==null&&m.entities().stream().anyMatch(x->e.javaName().equals(x.parentJavaName()));}
    private String idType(GenerationModel m,GenerationEntity e){if(e.parentJavaName()==null)return e.id().javaType();return m.entities().stream().filter(x->x.javaName().equals(e.parentJavaName())).findFirst().map(x->idType(m,x)).orElse("UUID");}
    private String idField(GenerationModel m,GenerationEntity e){if(e.parentJavaName()==null)return e.id().javaName();return m.entities().stream().filter(x->x.javaName().equals(e.parentJavaName())).findFirst().map(x->idField(m,x)).orElse("id");}
    private GenerationEntity entityById(GenerationModel m,String id){return m.entities().stream().filter(x->x.sourceElementId().equals(id)).findFirst().orElseThrow();}
    private boolean ownsManyToMany(GenerationModel m,GenerationEntity e,GenerationRelationship r){if(!r.multiple())return false;if("ClassUnidirectional".equals(r.originalType()))return e.sourceElementId().equals(r.sourceId());GenerationEntity source=entityById(m,r.sourceId()),target=entityById(m,r.targetId());GenerationEntity owner=source.tableName().compareTo(target.tableName())<=0?source:target;return owner.sourceElementId().equals(e.sourceElementId());}
    private String accessors(String type,String name){return "  public "+type+" get"+cap(name)+"(){return "+name+";}\n  public void set"+cap(name)+"("+type+" "+name+"){this."+name+"="+name+";}\n";}
    private String lower(String s){return Character.toLowerCase(s.charAt(0))+s.substring(1);}private String cap(String s){return Character.toUpperCase(s.charAt(0))+s.substring(1);}private String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}private String java(String s){return s.replace("\\","\\\\").replace("\"","\\\"");}private void put(Map<String,byte[]>m,String p,String c){m.put(p,c.getBytes(StandardCharsets.UTF_8));}
}
